package com.transiva.app;
import android.content.Context; import java.io.*; import java.net.*; import java.nio.charset.StandardCharsets;
public final class TransAssistantSync { private TransAssistantSync(){} public static void sync(Context c){ new Thread(()->{ HttpURLConnection h=null; try{h=CustomerApiClient.open(c,ApiConfig.server("trans_assistant_knowledge.php")); h.setRequestMethod("GET"); int code=h.getResponseCode(); InputStream in=code>=200&&code<300?h.getInputStream():h.getErrorStream(); StringBuilder b=new StringBuilder(); if(in!=null){BufferedReader r=new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));String s;while((s=r.readLine())!=null)b.append(s);} if(!CustomerApiClient.handleSessionResponse(c,code,b.toString()) && code>=200&&code<300) TransAssistantKnowledge.saveRemote(c,b.toString()); }catch(Exception ignored){}finally{if(h!=null)h.disconnect();}} ,"TransAssistantSync").start(); } }
